import numpy as np

def garch_forecast(params, last_r, last_s2, h):
    """Daily variance forecasts for the next h days, made at the end of the day
    whose return was last_r and whose variance was last_s2 (returns in %)."""
    omega, alpha, beta = params
    out = []
    s2 = omega + alpha * last_r ** 2 + beta * last_s2   # tomorrow
    for k in range(h):
        out.append(float(s2))
        s2 = omega + (alpha + beta) * s2                 # E[r^2] = E[sigma^2]
    return out

def horizon_vol(forecasts):
    return float(np.sqrt(np.sum(forecasts)))

import numpy as np

def forecast_from_series(params, r, h):
    """Daily variance forecasts for the h days after the last day of r (returns in %)."""
    s2 = garch_variance(params, r)
    return garch_forecast(params, r[-1], s2[-1], h)

def annual_vol_forecast(params, r):
    """Volatility over the next 252 trading days, as a fraction."""
    return horizon_vol(forecast_from_series(params, r, 252)) / 100
